import json
from pathlib import Path
import sys

import pytest
import torch

from ai_journey.http_load_report import verify_http_load_report
from ai_journey.http_readiness import run_installed_http_readiness


def test_readiness_runs_console_entry_protocol_against_actual_server_and_restores_runtime(
    tmp_path,
):
    # Exercise readiness orchestration with the same console shim generated by
    # package installers. The dedicated CI step invokes the installed command.
    command = tmp_path / "ai-journey-http-load"
    command.write_text(
        f"#!{sys.executable}\nfrom ai_journey.http_load_cli import main\nraise SystemExit(main())\n"
    )
    command.chmod(0o755)
    output = tmp_path / "http-readiness.json"
    rng = torch.get_rng_state().clone()
    dtype, threads = torch.get_default_dtype(), torch.get_num_threads()
    summary = run_installed_http_readiness(output, command=command)
    assert summary["measured_requests"] == 8
    assert summary["measured_output_tokens"] == 32
    assert summary["server_requests_including_warmup"] == 9
    verify_http_load_report(json.loads(output.read_text()))
    assert torch.get_default_dtype() == dtype
    assert torch.get_num_threads() == threads
    assert torch.equal(torch.get_rng_state(), rng)
    with pytest.raises(ValueError, match="already exists"):
        run_installed_http_readiness(output, command=command)


def test_readiness_requires_installed_command_and_ci_covers_http_pytest_functions(
    tmp_path,
):
    with pytest.raises(ValueError, match="installed"):
        run_installed_http_readiness(
            tmp_path / "output.json", command=tmp_path / "missing"
        )
    root = Path(__file__).resolve().parents[1]
    workflow = (root / ".github/workflows/ci.yml").read_text()
    assert "ruff check src/ai_journey/http_*.py tests/test_http_*.py" in workflow
    assert "python -m pytest -q tests/test_http_*.py" in workflow
    assert (
        "ai-journey-http-load readiness --output /tmp/ddp-ci/http-load-readiness.json"
        in workflow
    )
    required = json.loads((root / "config/deployment_readiness.json").read_text())[
        "required_files"
    ]
    assert "src/ai_journey/http_readiness.py" in required
    assert "tests/test_http_readiness.py" in required
